package com.example.evolvix.data.model

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey
import java.time.LocalDateTime

/**
 * Database entity representing a habit.
 * Stores all essential information about a habit including progress tracking and appearance.
 *
 * @property id Unique identifier, auto-generated by Room
 * @property name Display name of the habit
 * @property currentCount Current progress towards target
 * @property frequency How often the habit should be performed
 * @property target Goal to reach before considering habit complete
 * @property totalProgressUpdates Total number of progress increments
 * @property totalTargetReaches Number of times target was reached
 * @property lastResetDate When the progress was last reset
 * @property colorHex Hex color string for the habit (e.g. "#4CAF50")
 * @property categories List of category labels assigned to this habit (e.g. "Health", "Fitness")
 * @property iconKey Optional key identifying the habit's icon; null means auto-resolved
 * @property sortOrder Manual drag-and-drop position within the list (lower = higher up)
 * @property categoryGroup Optional group label used when habits are displayed by category * @property frequencyN The "every N" multiplier for the habit's [frequency] unit (e.g. 2 for "every 2 weeks").
 *   Defaults to 1. Used by [FREQ_ASC]/[FREQ_DESC] sort modes. */
@Entity(tableName = "habits", indices = [Index(value = ["name"], unique = true)])
data class HabitEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val name: String,
    val currentCount: Int,
    val frequency: HabitFrequency = HabitFrequency.Daily,
    val target: Int,
    val totalProgressUpdates: Int = 0,
    val totalTargetReaches: Int = 0,
    val lastResetDate: LocalDateTime = LocalDateTime.now(),
    val colorHex: String = "#4CAF50",
    val categories: List<String> = emptyList(),
    val iconKey: String? = null,
    val reminderEnabled: Boolean = false,
    /**
     * User-chosen reminder time encoded as minutes-of-day (0 .. 1439).
     * Null means "let the AI pick" — Phase 7.1 `ScheduleReminderUseCase` will then
     * query [HabitPredictor.findOptimalHours] and schedule the first hour of the
     * top-ranked slot. When non-null, the value is treated as a fixed daily slot.
     */
    val reminderTime: Long? = null,
    /** Timestamp (millis since Unix epoch) until which the habit is paused. Null = active; Long.MAX_VALUE = paused indefinitely. */
    val pausedUntil: Long? = null,
    /** Manual sort position for drag-and-drop ordering; lower value = higher in the list. */
    val sortOrder: Int = 0,
    /** Optional category group label used when grouping habits by category in the list. */
    val categoryGroup: String? = null,
    /** User-created group name in MANUAL sort mode; null = ungrouped. */
    val manualGroup: String? = null,
    /** Sort position of the group itself in MANUAL mode (Phase B — group-level drag). */
    val groupSortOrder: Int = 0,
    /** The "every N" multiplier for [frequency] (e.g. 2 for "every 2 weeks"). Defaults to 1. */
    val frequencyN: Int = 1
)